// ABOUTME: Property tests for annual aggregation and progression, generated by a seeded fast-check
// ABOUTME: run so a failure reproduces: equal-weight weighted means agree with means under
// ABOUTME: renormalise, best_of is order-independent, every threshold holds at its bound and fails
// ABOUTME: just below it, and an annual trace replays into its own value.

import * as fc from 'fast-check';
import { describe, it } from 'vitest';

import { formatExact, parseExact, subtractExact } from '@/domain/assessment/engine';

import { evaluateAnnual, evaluateProgression, replayAnnual } from '..';
import type { AnnualDefinition, AnnualPeriodInput, ProgressionDefinition } from '..';
import { STRUCTURE, learnerAt } from './fixtures';

const OPTIONS = { seed: 20261021, numRuns: 80 } as const;

const presence = fc.array(fc.tuple(fc.integer({ min: 0, max: 100 }).map(String), fc.boolean()), {
  minLength: 1,
  maxLength: 6,
});

const somePresent = presence.filter((entries) => entries.some(([, present]) => present));

function periodInputs(entries: readonly (readonly [string, boolean])[]): readonly AnnualPeriodInput[] {
  return entries.map(([value, present], index) => ({
    code: `T${index + 1}`,
    ...(present ? { value } : {}),
  }));
}

describe('annual aggregation', () => {
  it('makes an equal-weight weighted mean equal the mean of the same periods under renormalise', () => {
    fc.assert(
      fc.property(somePresent, (entries) => {
        const codes = entries.map((_, index) => `T${index + 1}`);
        const weights = Object.fromEntries(codes.map((code) => [code, `1/${codes.length}`]));
        const periods = periodInputs(entries);
        const weighted = evaluateAnnual(
          { op: 'weighted_mean', of: weights, missing: 'renormalise' },
          periods
        );
        const mean = evaluateAnnual({ op: 'mean', of: codes, missing: 'renormalise' }, periods);
        if (!weighted.ok || !mean.ok) return false;
        return weighted.result.value === mean.result.value;
      }),
      OPTIONS
    );
  });

  it('selects the same best_of periods whatever order the inputs and the declared list arrive in', () => {
    fc.assert(
      fc.property(somePresent, fc.integer({ min: 1, max: 6 }), (entries, rawN) => {
        const present = entries.filter(([, isPresent]) => isPresent).length;
        const n = Math.min(rawN, present);
        const codes = entries.map((_, index) => `T${index + 1}`);
        const definition: AnnualDefinition = { op: 'best_of', of: codes, n, missing: 'renormalise' };
        const reverseOf: AnnualDefinition = { op: 'best_of', of: [...codes].reverse(), n, missing: 'renormalise' };
        const periods = periodInputs(entries);
        const forward = evaluateAnnual(definition, periods);
        const backward = evaluateAnnual(reverseOf, [...periods].reverse());
        if (!forward.ok || !backward.ok) return false;
        return (
          forward.result.value === backward.result.value &&
          forward.result.average.consumed.map((entry) => entry.code).join(',') ===
            backward.result.average.consumed.map((entry) => entry.code).join(',')
        );
      }),
      OPTIONS
    );
  });

  it('replays a best_of trace into its own value', () => {
    fc.assert(
      fc.property(somePresent, fc.integer({ min: 1, max: 6 }), (entries, rawN) => {
        const present = entries.filter(([, isPresent]) => isPresent).length;
        const codes = entries.map((_, index) => `T${index + 1}`);
        const definition: AnnualDefinition = {
          op: 'best_of',
          of: codes,
          n: Math.min(rawN, present),
          missing: 'renormalise',
        };
        const evaluation = evaluateAnnual(definition, periodInputs(entries));
        if (!evaluation.ok) return false;
        const replayed = replayAnnual(
          JSON.parse(JSON.stringify(evaluation.result.trace)) as typeof evaluation.result.trace
        );
        return replayed.value === evaluation.result.value;
      }),
      OPTIONS
    );
  });
});

describe('threshold', () => {
  const bound = fc.integer({ min: 1, max: 1000 }).map((value) => (value / 10).toFixed(1));

  it('passes at every bound and fails one hundredth below each one', () => {
    fc.assert(
      fc.property(fc.array(bound, { minLength: 1, maxLength: 4 }), (bounds) => {
        const conditions = bounds.map((gte, index) => ({ metric: `annual.M${index}`, gte }));
        const definition: ProgressionDefinition = {
          progression: [{ levels: ['L3'], rule: 'threshold', conditions, else: 'repeat_or_council' }],
        };
        const met = Object.fromEntries(
          conditions.map((condition) => [condition.metric, { value: condition.gte, complete: true }])
        );
        const passing = evaluateProgression(definition, [learnerAt('L3')], { ...STRUCTURE, metrics: met });
        if (!passing.ok || passing.suggestions[0].action !== 'promote') return false;

        for (const condition of conditions) {
          const exact = parseExact(condition.gte);
          const cent = parseExact('0.01');
          if (exact === null || cent === null) return false;
          const below = formatExact(subtractExact(exact, cent));
          const failing = evaluateProgression(definition, [learnerAt('L3')], {
            ...STRUCTURE,
            metrics: { ...met, [condition.metric]: { value: below, complete: true } },
          });
          if (!failing.ok) return false;
          if (failing.suggestions[0].action === 'promote') return false;
          if (!failing.suggestions[0].reasons.some((reason) => reason.code === 'threshold_failed')) return false;
        }
        return true;
      }),
      { ...OPTIONS, numRuns: 60 }
    );
  });
});
